  <script>
    const addButtons = document.querySelectorAll("[data-product]");
    const cartCount = document.querySelector("#cart-count");
    const cartStatus = document.querySelector("#cart-status");
    const cartLabel = document.querySelector("#cart-label");
    const newsletterForm = document.querySelector(".newsletter-form");
    const emailInput = document.querySelector("#email");
    const formStatus = document.querySelector("#form-status");

    let itemCount = 0;

    function itemLabel(count) {
      return count === 1 ? "item" : "items";
    }

    addButtons.forEach((button) => {
      const productName = button.dataset.product;
      button.setAttribute("aria-label", `Add to bag: ${productName}`);

      button.addEventListener("click", () => {
        itemCount += 1;
        cartCount.textContent = itemCount;
        cartLabel.textContent = `, ${itemCount} ${itemLabel(itemCount)}`;
        cartStatus.textContent = `${productName} added to your bag. Bag now has ${itemCount} ${itemLabel(itemCount)}.`;
      });
    });

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!emailInput.validity.valid) {
        emailInput.setAttribute("aria-invalid", "true");
        emailInput.setAttribute("aria-errormessage", "form-status");
        formStatus.textContent = "Enter a valid email address before signing up.";
        emailInput.focus();
        return;
      }

      emailInput.removeAttribute("aria-invalid");
      emailInput.removeAttribute("aria-errormessage");
      formStatus.textContent = "Thanks. You are on the list for early access and private sale alerts.";
      newsletterForm.reset();
    });

    emailInput.addEventListener("input", () => {
      if (emailInput.getAttribute("aria-invalid") === "true" && emailInput.validity.valid) {
        emailInput.removeAttribute("aria-invalid");
        emailInput.removeAttribute("aria-errormessage");
        formStatus.textContent = "";
      }
    });
