    const page = await browser.newPage({ viewport });
    await page.goto(`file://${path.resolve('index.html')}`, { waitUntil: 'load' });
    results.push(await scan(page, `initial ${viewport.width}`));
    await page.locator('[data-product="Canvas Weekender Tote"]').click();
    results.push(await scan(page, `cart update ${viewport.width}`));
    await page.locator('.newsletter-form button[type="submit"]').click();
    results.push(await scan(page, `invalid form ${viewport.width}`));
    await page.close();
  }
  await browser.close();
  console.log(JSON.stringify(results, null, 2));
  if (results.some((r) => r.wcag.length)) process.exit(1);
})();
